{
  "Server": {
    "ListenerHostname": "*",
    "ListenerPort": 8000,
    "Ssl": false,
    "Debug": false,
    "RequireAuthentication": true,
    "ApiKeyHeader": "x-api-key"
  },
  "Logging": {
    "ServerIp": "127.0.0.1",
    "ServerPort": 514,
    "MinimumLevel": 1,
    "LogHttpRequests": false,
    "LogHttpResponses": false,
    "ConsoleLogging": true
  },
  "Databases": [
    {
      "Name": "sample",
      "Type": "Sqlite",
      "Filename": "./sample.db",
      "Debug": false,
      "Tables": [],
      "TableNames": []
    }
  ],
  "ApiKeys": [
    {
      "Key": "default",
      "AllowGet": true,
      "AllowPost": true,
      "AllowPut": true,
      "AllowDelete": true
    }
  ]
}

{
  "Databases": {
    "sample": {
      "Context": "This SQLite database contains example business data used to explore RestDb and the dashboard.",
      "Tables": {
        "department": "Reference table for departments. Primary key is department_id.",
        "person": "Stores people records. Primary key is person_id and department_id relates each person to a department.",
        "project": "Stores projects owned by departments. Primary key is project_id and department_id links each project to a department.",
        "task": "Stores task records assigned to people and projects. Primary key is task_id, with project_id and assignee_person_id describing ownership and assignment."
      }
    }
  }
}

